from lib import *
S = SS('k78')
F1 = [['kubectl debug app --image=busybox', '--container=dbg1(无 --target)'], ['dbg1 的 ps', '只看到自己'], ['dbg2 --target=main', '共享进程命名空间'], ['dbg2 的 ps', 'nginx master + 6 worker'], ['想删临时容器', 'Forbidden']]
F2 = [['--copy-to=app-copy', '换镜像换命令'], ['原 Pod', '不动'], ['--share-processes', 'app-share'], ['dbg3 里 ps', '看到 nginx 进程']]
F3 = [['kubectl debug node/worker', ''], ['node-debugger Pod', 'hostNetwork/PID/IPC + / 挂到 /host'], ['privileged: true', ''], ['chroot /host', '看到节点自己的系统']]
F4 = [['general', 'SYS_PTRACE'], ['baseline', '无'], ['restricted', 'drop ALL + 非 root'], ['netadmin', 'NET_ADMIN, NET_RAW'], ['sysadmin', 'privileged']]
PANELS = [('f', 'flow', 'kubectl debug'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("Pod app 的主容器是 nginx(readOnlyRootFilesystem)。kubectl debug app --image=busybox:1.36 --container=dbg1 往运行中的 Pod 里加了一个临时容器:Pod 的 spec.ephemeralContainers 里多了它,主容器 restartCount 仍是 0。dbg1 没有 --target,ps 只看到自己(PID 1 是它自己的 sh);dbg2 加了 --target=main,加入主容器的进程命名空间,ps 看到 PID 1 是 nginx master 和 6 个 worker,还能通过 /proc/1/root 看到主容器的文件系统(/etc/nginx)。临时容器删不掉(patch remove 被拒:pod updates may not change fields other than …),也不能带 resources(cannot be set for an Ephemeral Container)。", f=fl(F1, cur=[2, 3], mark=[4], done=[0, 1]), t=tl(S(1), mark=lidx(S(1), 'dbg1 的输出', 'dbg2(--target=main'), done=lidx(S(1), '想删除一个临时容器', 'restartCount=0')), kv=KV([['临时容器', '给运行中的 Pod 加调试工具,不重启 Pod'], ['--target', '加入目标容器的进程命名空间'], ['不能删', '创建后不可移除,Pod 重建才消失']], ['临时容器'])),
    step("kubectl debug app --copy-to=app-copy --image=busybox:1.36 -- sleep 3600:复制出一个独立的 Pod(没有 ownerReferences,调度器把它放到 worker2,原 Pod 在 worker),main 容器换成 busybox 并改了命令;原 Pod 的 main 仍是 nginx,没有被动过。再用 --share-processes 复制出 app-share(shareProcessNamespace=true,容器 main 和 dbg3),在 dbg3 里 ps 能看到 /pause 和 nginx 进程。", f=fl(F2, cur=[0, 2], done=[1, 3]), t=tl(S(2), mark=lidx(S(2), '--copy-to=app-copy', '--share-processes'), done=lidx(S(2), '原 Pod 没动', '在 dbg3 里 ps')), kv=KV([['--copy-to', '不碰原 Pod,在副本上随便改'], ['副本要手动删', '没有控制器,调试完自己清理'], ['--share-processes', '副本里容器能互相看到进程']], ['--copy-to'])),
    step("kubectl debug node/kx-main-worker --image=busybox:1.36 -- chroot /host …:创建了一个叫 node-debugger-kx-main-worker-<随机> 的 Pod(在 default 命名空间),nodeName 是 worker,hostNetwork=true、hostPID=true、hostIPC=true,hostPath / 挂在 /host,容器 securityContext 是 privileged: true(用了 sysadmin 配置)。chroot /host 后看到的主机名是 kx-main-worker,crictl ps 有 6 行,os-release 是 Debian GNU/Linux 13——已经是节点自己的系统了。", f=fl(F3, cur=[1], done=[0, 2, 3]), t=tl(S(3), mark=lidx(S(3), 'hostNetwork=True', 'privileged'), done=lidx(S(3), '在节点根目录里')), kv=KV([['节点调试 Pod', '共享宿主机的网络/PID/IPC,根目录在 /host'], ['权限很大', '等同于 root 登录节点'], ['调试完要删', '它是一个普通 Pod']], ['权限很大'])),
    step("--profile 决定调试容器的权限:general 加 SYS_PTRACE;baseline 没有额外 securityContext;restricted 要求 allowPrivilegeEscalation=false、drop ALL、runAsNonRoot、seccomp RuntimeDefault;netadmin 加 NET_ADMIN 和 NET_RAW;sysadmin 是 privileged: true。", f=fl(F4, cur=[0, 1, 2, 3, 4]), t=tl(S(4), mark=lidx(S(4), 'general', 'sysadmin'), done=lidx(S(4), 'restricted')), kv=KV([['restricted', '在 restricted 命名空间里也能用'], ['netadmin', '抓包、改路由所需'], ['sysadmin', 'privileged,最后手段']], ['restricted'])),
]
A = mkartk('k78', 78, 'Kubernetes,kubectl debug,临时容器,ephemeralContainers,节点调试,真实验证,动画演示',
    '在 kind 集群里实测 kubectl debug 的三种用法:往运行中的 Pod 加临时容器(--target 才能看到主容器的进程,临时容器不能删、不能设 resources、主容器不会重启);--copy-to 复制出独立的 Pod,在副本里换镜像换命令而原 Pod 不动,加 --share-processes 共享进程;debug node 创建 hostNetwork / hostPID / hostIPC 且挂载宿主机根目录的 privileged Pod,chroot /host 后就是节点自己的系统;--profile 的五种权限配置。',
    '线上容器没有 shell,怎么排查?kubectl debug 的临时容器和直接 exec 有什么不同?复制 Pod、调试节点各自做了什么?profile 又改变了什么?这篇一个个实际执行,把生成的 Pod spec 也读出来。',
    [('0 次重启', '加临时容器后主容器 restartCount 仍为 0,Pod uid 不变'), ('privileged', 'debug node 生成的 Pod:hostNetwork / hostPID / hostIPC + / 挂到 /host'), ('5 种 profile', 'general / baseline / restricted / netadmin / sysadmin 对应的 securityContext 各不相同')],
    [('临时容器', '<p>Pod <code>app</code> 的主容器是 nginx(只读根文件系统,没有调试工具)。<code>kubectl debug app --image=busybox:1.36 --container=dbg1</code> 往运行中的 Pod 加了一个临时容器,Pod 的 <code>spec.ephemeralContainers</code> 多了一项,主容器 <code>restartCount</code> 仍是 0、uid 不变。<code>dbg1</code> 没有 <code>--target</code>,<code>ps</code> 只看到自己;<code>dbg2</code> 加了 <code>--target=main</code>,加入主容器的进程命名空间,<code>ps</code> 看到 PID 1 是 nginx master 和 6 个 worker,还能通过 <code>/proc/1/root</code> 读主容器的 <code>/etc/nginx</code>。临时容器创建后删不掉(<code>patch remove</code> 被拒:<code>pod updates may not change fields other than …</code>),也不能设置 <code>resources</code>。</p>'),
     ('复制一份来调试', '<p><code>kubectl debug app --copy-to=app-copy --image=busybox:1.36 -- sleep 3600</code> 复制出一个独立的 Pod(没有 ownerReferences,调度器把它放在 worker2,原 Pod 在 worker),main 容器换成 busybox 并改了命令;原 Pod 的 main 仍是 nginx,没有被动过。加 <code>--share-processes</code> 复制出 <code>app-share</code>(<code>shareProcessNamespace=true</code>),在 <code>dbg3</code> 里 <code>ps</code> 能看到 <code>/pause</code> 和 nginx 进程。副本是个普通 Pod,调试完要自己删。</p>'),
     ('调试节点', '<p><code>kubectl debug node/kx-main-worker --image=busybox:1.36 -- chroot /host …</code> 创建了一个叫 <code>node-debugger-kx-main-worker-…</code> 的 Pod(在 <code>default</code> 命名空间),<code>nodeName</code> 是 worker,<code>hostNetwork</code>、<code>hostPID</code>、<code>hostIPC</code> 都是 true,宿主机根目录挂在 <code>/host</code>,容器是 <code>privileged: true</code>(<code>sysadmin</code> 配置)。<code>chroot /host</code> 之后看到的主机名是 <code>kx-main-worker</code>,<code>crictl ps</code> 有 6 行,os-release 是 Debian GNU/Linux 13——已经是节点自己的系统。这个 Pod 的权限等同于 root 登录节点。</p>'),
     ('profile', '<p><code>--profile</code> 决定调试容器的 securityContext:<code>general</code> 加 <code>SYS_PTRACE</code>;<code>baseline</code> 没有额外设置;<code>restricted</code> 要求 <code>allowPrivilegeEscalation=false</code>、drop ALL、<code>runAsNonRoot</code>、seccomp RuntimeDefault(能在 restricted 的命名空间里用);<code>netadmin</code> 加 <code>NET_ADMIN</code> 和 <code>NET_RAW</code>;<code>sysadmin</code> 是 <code>privileged: true</code>。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0);目标 Pod 是只读根文件系统的 nginx:1.27-alpine,调试镜像 busybox:1.36;因为是脚本非交互执行,命令用 -- 带一次性命令,输出用 kubectl logs -c 取回;节点调试的 Pod 生成在 default 命名空间,实验后已删除;每种情形各一次',
     '没有验证:交互式 kubectl debug -it 的附着行为;--target 在不支持的运行时上的表现(会静默忽略);ephemeralContainers 对 Pod 状态与资源计量的影响;Windows 节点调试;kubectl debug 的 --custom 自定义;临时容器与 PodSecurity 准入;/proc/1/environ 读取其他容器环境变量需要的权限(实验中没有得到稳定结果)'],
    'kubectl debug', PANELS)
